using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using QuanLyKho.DTOs;using QuanLyKho.Services;namespace QuanLyKho.Controllers;[ApiController][Route("api/auth")]public sealed class AccountController:ControllerBase{readonly AuthService s;public AccountController(AuthService s)=>this.s=s;[AllowAnonymous][HttpPost("login")]public async Task<IActionResult> Login(LoginRequest r)=>Ok(await s.LoginAsync(r));[Authorize][HttpGet("me")]public async Task<IActionResult> Me()=>Ok(await s.MeAsync(int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!)));}